'use strict';
// All artwork is preloaded; sprite cells are normalized and padded to prevent atlas bleed.
const TREASURE8_IMAGES=[new Image(),new Image()];
TREASURE8_IMAGES[0].src='assets/treasures-v8.webp';
TREASURE8_IMAGES[1].src='assets/reward-frames-v8.webp';
function treasureSprite8(index,x,y,size){const im=TREASURE8_IMAGES[0];if(!im.complete||!im.naturalWidth)return false;const s=im.naturalWidth/4;ctx.drawImage(im,index%4*s,Math.floor(index/4)*s,s,s,x-size/2,y-size/2,size,size);return true;}
function treasureAppearance8(c){if(c.type==='chest')return 5;const group=Number.isFinite(c.group)?c.group:0,kind=relicKind(c);if(kind==='starcoin')return 4;if(kind==='pearl')return group%4===0?0:[10,11,13][group%3];if(kind==='ruby')return 1;if(kind==='aqua')return 2;if(kind==='amethyst')return 3;return [0,2,3,4,8,9,10,11][((group+Math.max(0,stage))%8+8)%8];}
function rewardFrame8(index,x,y,w,h){const im=TREASURE8_IMAGES[1];if(!im.complete||!im.naturalWidth)return false;const s=im.naturalWidth/3;ctx.drawImage(im,index%3*s,Math.floor(index/3)*s,s,s,x-w/2,y-h/2,w,h);return true;}
function drawRewardPopup8(p,t){const kind=p.kind||'plain';if(kind==='plain')return false;const x=p.x-camera;if(x<-180||x>vw+180)return true;ctx.save();const progress=clamp(1-p.life/(p.maxLife||1.15),0,1);ctx.globalAlpha=Math.min(1,p.life*3);ctx.translate(x,p.y);const scale=reducedMotion?1:1+Math.sin(progress*Math.PI)*.075;ctx.scale(scale,scale);const decorated=['treasure','combo','perfect','heart','pearl'].includes(kind);if(decorated){const frame={treasure:4,combo:1,perfect:2,heart:3,pearl:0}[kind];rewardFrame8(frame,0,-7,186,116);ctx.fillStyle='#073958e8';ctx.beginPath();ctx.roundRect(-68,-11,136,30,14);ctx.fill();}const bonus=decorated?/^(\+\d+)\s+(.+)$/.exec(p.text):null,label=bonus?bonus[1]:p.text;ctx.textAlign='center';ctx.textBaseline='middle';ctx.font='600 '+(decorated?19:23)+'px TreasureDisplay,Nunito,sans-serif';ctx.lineWidth=decorated?3:4;ctx.strokeStyle='#123756';ctx.strokeText(label,0,decorated?3:0);ctx.fillStyle=kind==='heart'?'#ffe7f3':'#fff3ba';ctx.fillText(label,0,decorated?3:0);if(bonus){ctx.font='600 10px TreasureDisplay,Nunito,sans-serif';ctx.lineWidth=2;ctx.strokeText(bonus[2],0,22);ctx.fillText(bonus[2],0,22);};ctx.restore();return true;}
function installTreasureUI8(){
 const oldGold=drawGold,oldPowerup=drawPowerup,oldRelic=drawRelicArtwork;
 drawGold=function(c,t){const x=c.x-camera;if(c.taken||x<-90||x>vw+90)return;const y=c.y+(reducedMotion?0:Math.sin(t*2+c.phase)*5);ctx.save();ctx.translate(x,y);if(!reducedMotion)ctx.rotate(Math.sin(t*1.4+c.phase)*.065);const ok=treasureSprite8(treasureAppearance8(c),0,0,c.type==='chest'?79:49);ctx.restore();if(!ok)oldGold(c,t);};
 drawPowerup=function(p,t){if(p.type==='bubble-rush'){oldPowerup(p,t);return;}const x=p.x-camera;if(p.taken||x<-90||x>vw+90)return;const y=p.y+(reducedMotion?0:Math.sin(t*2.5+p.phase)*9);if(!treasureSprite8(p.type==='heart'?6:7,x,y,66)){oldPowerup(p,t);return;}ctx.save();ctx.strokeStyle=p.type==='heart'?'#ffc8e780':'#a6fbff80';ctx.lineWidth=1.5;ctx.beginPath();ctx.arc(x,y,39,0,Math.PI*2);ctx.stroke();ctx.restore();};
 drawRelicArtwork=function(x,y,size,variant=0){return treasureSprite8([12,14,15,11][((variant%4)+4)%4],x,y,size)||oldRelic(x,y,size);};
}
